send_environment_vars(ConnectionRef, Channel, VarNames) ->
    lists:foldl(
      fun(Var, success) ->
              case os:getenv(Var) of
                  false ->
                      success;
                  Value ->
                      setenv(ConnectionRef, Channel, false,
                             Var, Value, infinity)
              end
      end, success, VarNames).

